<script setup lang="ts">
/**
 * The page outside the shell: sign-in, sign-up, a setup step, a status (`design/archetypes/auth-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/auth-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, useTemplateRef, watch } from 'vue'

import { PageTransition } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/auth-page.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import Card from '../structure/Card.vue'

export interface AuthPageProps {
  /**
   * The layout, where `illustrated` is the public account layout with host-supplied artwork.
   */
  layout?: 'centered' | 'illustrated'
  pending?: boolean
  /**
   * The `<h1>`.
   */
  title: string
  transitionKey?: string
}

defineOptions({ name: 'AuthPage', inheritAttrs: false })

const props = withDefaults(defineProps<AuthPageProps>(), { layout: 'centered', pending: false })
defineSlots<{
  backAction?: (props: Record<string, never>) => unknown
  brand?: (props: Record<string, never>) => unknown
  cardFooter?: (props: Record<string, never>) => unknown
  default?: (props: Record<string, never>) => unknown
  description?: (props: Record<string, never>) => unknown
  footer?: (props: Record<string, never>) => unknown
  illustration?: (props: Record<string, never>) => unknown
}>()
const body = useTemplateRef<HTMLElement>('body')
const illustrated = computed(() => props.layout === 'illustrated')
const effect1 = () => {
  illustrated.value &&
    body.value
      ?.querySelectorAll('[data-auth-enter]')
      .forEach((item, index) =>
        (item as HTMLElement).style.setProperty(
          '--pm-page-enter-order',
          String(Math.min(index, 9)),
        ),
      )
}
onMounted(effect1)
watch(() => [illustrated.value, props.transitionKey], effect1, { flush: 'post' })
</script>

<template>
  <main
    :class="[styles.page, illustrated ? styles.illustrated : undefined]"
    :aria-busy="pending ? true : undefined"
    :data-auth-layout="layout"
    data-member="auth-page"
  >
    <!-- topbar -->
    <div v-if="illustrated && $slots.brand" :class="styles.topbar">
      <slot name="brand" />
    </div>
    <!-- body -->
    <div ref="body" :class="styles.body">
      <!-- column -->
      <component
        :is="PageTransition"
        :class="[styles.column, transitionKey !== undefined ? transitions.page : undefined]"
        as="div"
        :transitionKey="transitionKey"
        :pending="pending"
        :ribbon="transitions.indicator"
      >
        <!-- illustration -->
        <div
          v-if="illustrated && $slots.illustration"
          :class="styles.illustration"
          aria-hidden="true"
        >
          <slot name="illustration" />
        </div>
        <!-- formColumn -->
        <div :class="styles.formColumn">
          <!-- brand -->
          <div v-if="!illustrated && $slots.brand" :class="styles.brand">
            <slot name="brand" />
          </div>
          <!-- frame -->
          <div v-if="illustrated" :class="styles.frame">
            <!-- card -->
            <div :class="styles.card">
              <!-- heading -->
              <div :class="styles.heading" data-auth-enter="">
                <!-- titleRow -->
                <div :class="[styles.titleRow, $slots.backAction ? styles.withBack : undefined]">
                  <!-- backAction -->
                  <div v-if="$slots.backAction" :class="styles.backAction">
                    <slot name="backAction" />
                  </div>
                  <!-- title -->
                  <h1 :class="styles.title">
                    {{ title }}
                  </h1>
                </div>
                <!-- description -->
                <p v-if="$slots.description" :class="styles.description">
                  <slot name="description" />
                </p>
              </div>
              <slot />
              <!-- cardFooter -->
              <div v-if="$slots.cardFooter" :class="styles.cardFooter">
                <slot name="cardFooter" />
              </div>
            </div>
          </div>
          <Card v-else>
            <!-- card -->
            <div :class="styles.card">
              <!-- heading -->
              <div :class="styles.heading" data-auth-enter="">
                <!-- titleRow -->
                <div :class="[styles.titleRow, $slots.backAction ? styles.withBack : undefined]">
                  <!-- backAction -->
                  <div v-if="$slots.backAction" :class="styles.backAction">
                    <slot name="backAction" />
                  </div>
                  <!-- title -->
                  <h1 :class="styles.title">
                    {{ title }}
                  </h1>
                </div>
                <!-- description -->
                <p v-if="$slots.description" :class="styles.description">
                  <slot name="description" />
                </p>
              </div>
              <slot />
              <!-- cardFooter -->
              <div v-if="$slots.cardFooter" :class="styles.cardFooter">
                <slot name="cardFooter" />
              </div>
            </div>
          </Card>
          <!-- footer -->
          <div v-if="$slots.footer" :class="styles.footer">
            <slot name="footer" />
          </div>
        </div>
      </component>
    </div>
  </main>
</template>
